# One per AWS account. Template: terraform/accounts/solutions/aws/global/iam/github-actions. A person applies it.
data "aws_iam_policy_document" "assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::123456789012:role/GitHubActionsTerraformPlan"] # OIDC role, trusts PRs of infrastructure only
    }
  }
}

resource "aws_iam_role" "terraform_plan" {
  name               = "TerraformPlanRole"
  assume_role_policy = data.aws_iam_policy_document.assume.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "read_only" {
  role       = aws_iam_role.terraform_plan.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

# A plan needs configuration, never data: ReadOnlyAccess alone could read objects, secrets and tables.
data "aws_iam_policy_document" "no_data_reads" {
  statement {
    effect    = "Deny"
    actions   = ["s3:GetObject", "secretsmanager:GetSecretValue", "ssm:GetParameter*", "kms:Decrypt", "dynamodb:GetItem", "dynamodb:Query", "dynamodb:Scan"]
    resources = ["*"] # units whose data sources read secrets are skipped in PR plans
  }
}

resource "aws_iam_role_policy" "no_data_reads" {
  role   = aws_iam_role.terraform_plan.id
  policy = data.aws_iam_policy_document.no_data_reads.json
}
